/* Local Canvas Chart-compatible renderer. No network dependency. */
(function(g){'use strict';function Chart(ctx,config){this.ctx=ctx&&ctx.canvas?ctx:ctx.getContext('2d');this.canvas=this.ctx.canvas;this.config=config||{};this.draw();}Chart.prototype.draw=function(){var x=this.ctx,c=this.canvas,d=this.config.data||{},labels=d.labels||[],sets=d.datasets||[],values=[];sets.forEach(function(s){(s.data||[]).forEach(function(v){if(Number.isFinite(Number(v)))values.push(Number(v));});});c.width=c.clientWidth||700;c.height=c.clientHeight||280;x.clearRect(0,0,c.width,c.height);x.font='12px sans-serif';x.fillStyle='#64748b';if(!labels.length||!values.length){x.textAlign='center';x.fillText('No data available for this period',c.width/2,c.height/2);return;}var p={left:58,right:20,top:45,bottom:48},w=c.width-p.left-p.right,h=c.height-p.top-p.bottom,max=Math.max(1,Math.max.apply(null,values)),min=Math.min(0,Math.min.apply(null,values)),range=max-min;for(var tick=0;tick<=4;tick++){var y=p.top+h-h*tick/4;x.strokeStyle='#e2e8f0';x.beginPath();x.moveTo(p.left,y);x.lineTo(p.left+w,y);x.stroke();x.fillStyle='#475569';x.textAlign='right';x.fillText(String(Math.round((min+range*tick/4)*100)/100),p.left-7,y+4);}var isBar=this.config.type==='bar';sets.forEach(function(s,si){var data=s.data||[];var hue=s.borderColor||'#0f766e';x.strokeStyle=hue;x.fillStyle=s.backgroundColor||hue;x.beginPath();data.forEach(function(v,i){var px=p.left+w*(i+.5)/labels.length,py=p.top+h-(Number(v)-min)/range*h;if(isBar){var bw=Math.max(3,Math.min(40,w/labels.length*.65/sets.length));var offset=(si-(sets.length-1)/2)*bw;x.fillRect(px-bw/2+offset,py,bw,p.top+h-py);}else{if(i===0)x.moveTo(px,py);else x.lineTo(px,py);}});if(!isBar)x.stroke();});labels.forEach(function(l,i){var px=p.left+w*(i+.5)/labels.length;x.fillStyle='#475569';x.textAlign='center';x.fillText(String(l).slice(0,12),px,c.height-20);});var legendX=p.left;sets.forEach(function(s){x.fillStyle=s.borderColor||'#0f766e';x.fillRect(legendX,12,12,12);x.fillStyle='#334155';x.textAlign='left';var name=String(s.label||'Series');x.fillText(name,legendX+17,23);legendX+=Math.max(85,name.length*7+35);});};Chart.prototype.destroy=function(){};g.Chart=Chart;})(window);
